using System;
using System.Collections.Generic;
using UnityEngine;

namespace GeNa.Core
{
    /// <summary>
    /// Spline Extension that lists road segments generated by this spline and optionally
    /// dissolves their start and/or end into the terrain.
    /// </summary>
    [Serializable]
    [CreateAssetMenu(fileName = "Road Endpoint Fade", menuName = "Procedural Worlds/GeNa/Extensions/Road Endpoint Fade", order = 5)]
    public class GeNaRoadEndpointFadeExtension : GeNaSplineExtension
    {
        [SerializeField] protected float m_startHiddenLength;
        [SerializeField] protected float m_endHiddenLength;
        [SerializeField] protected float m_startFadeLength = 20f;
        [SerializeField] protected float m_endFadeLength = 20f;
        [SerializeField] protected int m_endpointDetail = 4;
        [SerializeField] protected float m_surfaceBreakup = 0.8f;
        [SerializeField] protected int m_seed = 1847;
        [SerializeField] protected List<GeNaRoadEndpointFadeSegment> m_segments = new List<GeNaRoadEndpointFadeSegment>();

        public float StartHiddenLength
        {
            get => m_startHiddenLength;
            set => m_startHiddenLength = Mathf.Max(0f, value);
        }
        public float EndHiddenLength
        {
            get => m_endHiddenLength;
            set => m_endHiddenLength = Mathf.Max(0f, value);
        }
        public float StartFadeLength
        {
            get => m_startFadeLength;
            set => m_startFadeLength = Mathf.Max(0.1f, value);
        }
        public float EndFadeLength
        {
            get => m_endFadeLength;
            set => m_endFadeLength = Mathf.Max(0.1f, value);
        }
        public int EndpointDetail
        {
            get => m_endpointDetail;
            set => m_endpointDetail = Mathf.Clamp(value, 1, 4);
        }
        public float SurfaceBreakup
        {
            get => m_surfaceBreakup;
            set => m_surfaceBreakup = Mathf.Clamp(value, 0f, GeNaRoadEndpointFadeProcessor.MaxSurfaceBreakup);
        }
        public int Seed
        {
            get => m_seed;
            set => m_seed = value;
        }
        public List<GeNaRoadEndpointFadeSegment> Segments => m_segments;

        public override void Execute()
        {
            if (!IsActive || Spline == null)
                return;
            ApplyToRoadMeshes();
        }

        protected override void OnActivate()
        {
            ApplyToRoadMeshes();
        }

        protected override void OnDeactivate()
        {
            RestoreAll();
        }

        protected override void OnDelete()
        {
            RestoreAll();
        }

        public void RefreshSegmentList()
        {
            if (Spline == null)
                return;
            SyncSegments(FindRoadSegments(Spline));
        }

        /// <summary>
        /// Syncs the segment list with the spline's generated road meshes and applies enabled fades.
        /// </summary>
        public void ApplyToRoadMeshes()
        {
            if (Spline == null)
                return;

            List<GeNaRoad> roads = FindRoadSegments(Spline);
            SyncSegments(roads);
            if (!IsActive)
            {
                RestoreAll();
                return;
            }

            if (GeNaUtility.GetActivePipeline() == Constants.RenderPipeline.BuiltIn)
                return;

            Shader fadeShader = GeNaRoadEndpointFadeProcessor.GetFadeShader();
            for (int i = 0; i < roads.Count; i++)
            {
                GeNaRoad road = roads[i];
                GeNaRoadEndpointFadeSegment segment = GetSegment(road.name);
                if (segment == null)
                    continue;

                MeshFilter filter = road.GetComponent<MeshFilter>();
                MeshRenderer renderer = road.GetComponent<MeshRenderer>();
                if (filter == null || renderer == null)
                    continue;

                GeNaRoadEndpointFadeState state = road.GetComponent<GeNaRoadEndpointFadeState>();
                if (!segment.HasFade)
                {
                    if (state != null)
                    {
                        state.Restore(filter, renderer);
                        GeNaEvents.Destroy(state);
                    }
                    continue;
                }

                if (fadeShader == null)
                {
                    GeNaDebug.LogWarning("Road Endpoint Fade shader is missing for the active render pipeline.");
                    return;
                }

                if (state == null)
                    state = road.gameObject.AddComponent<GeNaRoadEndpointFadeState>();
                state.hideFlags = HideFlags.HideInInspector;
                state.Capture(filter, renderer);
                if (state.SourceMesh == null)
                    continue;

                GeNaRoadEndpointFadeSettings settings = CreateSettings(segment);
                int hash = settings.GetHash();
                if (state.Matches(hash))
                    continue;

                Mesh generated = GeNaRoadEndpointFadeProcessor.Generate(state.SourceMesh, road.name, settings);
                if (generated == null)
                    continue;

                Material sourceMaterial = state.SourceMaterials != null && state.SourceMaterials.Length > 0
                    ? state.SourceMaterials[0]
                    : renderer.sharedMaterial;
                Material fadeMaterial = GeNaRoadEndpointFadeProcessor.CreateFadeMaterial(sourceMaterial, fadeShader);
                if (fadeMaterial == null)
                {
                    GeNaEvents.Destroy(generated);
                    continue;
                }

                state.SetGenerated(generated, fadeMaterial, hash);
                filter.sharedMesh = generated;
                renderer.sharedMaterials = new[] { sourceMaterial, fadeMaterial };
            }
        }

        public void RandomizeSeed()
        {
            m_seed = UnityEngine.Random.Range(1, int.MaxValue);
        }

        public static List<GeNaRoad> FindRoadSegments(GeNaSpline spline)
        {
            List<GeNaRoad> result = new List<GeNaRoad>();
            if (spline == null)
                return result;

            Transform parent = spline.transform.Find("Road Meshes");
            if (parent == null)
                return result;

            GeNaRoad[] roads = parent.GetComponentsInChildren<GeNaRoad>(true);
            for (int i = 0; i < roads.Length; i++)
            {
                GeNaRoad road = roads[i];
                if (road == null)
                    continue;
                if (road.name.StartsWith("IntersectionMesh", StringComparison.Ordinal))
                    continue;
                if (road.GetComponent<MeshFilter>() == null)
                    continue;
                result.Add(road);
            }
            result.Sort((a, b) => string.CompareOrdinal(a.name, b.name));
            return result;
        }

        private void SyncSegments(List<GeNaRoad> roads)
        {
            if (m_segments == null)
                m_segments = new List<GeNaRoadEndpointFadeSegment>();

            HashSet<string> names = new HashSet<string>();
            for (int i = 0; i < roads.Count; i++)
            {
                string segmentName = roads[i].name;
                names.Add(segmentName);
                if (GetSegment(segmentName) == null)
                    m_segments.Add(new GeNaRoadEndpointFadeSegment { m_segmentName = segmentName });
            }

            for (int i = m_segments.Count - 1; i >= 0; i--)
            {
                if (m_segments[i] == null || string.IsNullOrEmpty(m_segments[i].m_segmentName) || !names.Contains(m_segments[i].m_segmentName))
                    m_segments.RemoveAt(i);
            }
        }

        private GeNaRoadEndpointFadeSegment GetSegment(string segmentName)
        {
            for (int i = 0; i < m_segments.Count; i++)
            {
                if (m_segments[i] != null && m_segments[i].m_segmentName == segmentName)
                    return m_segments[i];
            }
            return null;
        }

        private GeNaRoadEndpointFadeSettings CreateSettings(GeNaRoadEndpointFadeSegment segment)
        {
            return new GeNaRoadEndpointFadeSettings
            {
                FadeStart = segment.m_blendStart,
                FadeEnd = segment.m_blendEnd,
                StartHiddenLength = m_startHiddenLength,
                EndHiddenLength = m_endHiddenLength,
                StartFadeLength = m_startFadeLength,
                EndFadeLength = m_endFadeLength,
                Subdivisions = m_endpointDetail,
                SurfaceBreakup = m_surfaceBreakup,
                Seed = m_seed
            };
        }

        private void RestoreAll()
        {
            if (Spline == null)
                return;
            List<GeNaRoad> roads = FindRoadSegments(Spline);
            for (int i = 0; i < roads.Count; i++)
            {
                GeNaRoad road = roads[i];
                GeNaRoadEndpointFadeState state = road.GetComponent<GeNaRoadEndpointFadeState>();
                if (state == null)
                    continue;
                state.Restore(road.GetComponent<MeshFilter>(), road.GetComponent<MeshRenderer>());
                GeNaEvents.Destroy(state);
            }
        }
    }

    [Serializable]
    public class GeNaRoadEndpointFadeSegment
    {
        public string m_segmentName = string.Empty;
        public bool m_blendStart;
        public bool m_blendEnd;

        public bool HasFade => m_blendStart || m_blendEnd;
    }
}
